ator&#34;&gt;@&lt;/span&gt; p       &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; int &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;6470&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;362&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;929&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;1389&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;2076&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;2522&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;2938&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;3258&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;3803&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;4288&lt;/span&gt; &lt;span class=&#34;token ellipsis&#34;&gt;...&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; Dim     &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; int &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;19212&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;6469&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; Dimnames&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;List of &lt;span class=&#34;token number&#34;&gt;2&