pan&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;157&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; use.umi           &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;FALSE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;158&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; do.scale          &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;TRUE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;159&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; do.center         &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;TRUE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;160&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; scale.max         &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; num &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;161&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; block.size        &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; num &lt;span class=&#34;token number&#34;&gt;1000&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;162&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; min.cells.to.block&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; num &lt;span class=&#34;token number&#34;&gt;3000&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;163&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; verbose           &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;FALSE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;164&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; RunPCA.RNA              &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;Formal class &lt;span class=&#34;token string&#34;&gt;&#39;SeuratCommand&#39;&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;package &lt;span class=&#34;token string&#34;&gt;&#34;SeuratObject&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; with &lt;span class=&#34;token number&#34;&gt;5&lt;/span&gt; slots&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;165&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; name       &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; chr &lt;span class=&#34;token string&#34;&gt;&#34;RunPCA.RNA&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;166&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; time.stamp &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; POSIXct&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; format&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;2025-01-22 16:23:49&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;167&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; assay.used &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; chr &lt;span class=&#34;token string&#34;&gt;&#34;RNA&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;168&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; call.string&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; chr &lt;span class=&#34;token string&#34;&gt;&#34;RunPCA(., npcs = 20, verbose = FALSE)&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;169&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; params     &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;List of &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;170&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; assay          &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; chr &lt;span class=&#34;token string&#34;&gt;&#34;RNA&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;171&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; npcs           &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; num &lt;span class=&#34;token number&#34;&gt;20&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;172&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; rev.pca        &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;FALSE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;173&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; weight.by.var  &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;TRUE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;174&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; verbose        &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; logi &lt;span class=&#34;token boolean&#34;&gt;FALSE&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;175&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; ndims.print    &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; int &lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;token number&#34;&gt;5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;1&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;2&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;4&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;5&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;176&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; nfeatures.print&lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; num &lt;span class=&#34;token number&#34;&gt;30&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;177&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; reduction.name &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; chr &lt;span class=&#34;token string&#34;&gt;&#34;pca&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;178&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; reduction.key  &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; chr &lt;span class=&#34;token string&#34;&gt;&#34;PC_&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;179&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  .. .. .. .. ..&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt; seed.use       &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; num &lt;span class=&#34;token number&#34;&gt;42&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;180&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  ..&lt;span class=&#34;token operator&#34;&gt;@&lt;/span&gt; tools       &lt;span class=&#34;token operator&#34;&gt;:&lt;/span&gt; list&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h2 id=&#34;seurat-对象的结构详解&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#seurat-对象的结构详解&#34;&gt;#&lt;/a&gt; Seurat 对象的结构详解&lt;/h2&gt;
&lt;h3 id=&#34;assays&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#assays&#34;&gt;#&lt;/a&gt; assays&lt;/h3&gt;
&lt;p&gt;&lt;code&gt;assays&lt;/code&gt;  是 Seurat 对象的核心，存储了基因表达矩阵以及其他相关数据。本例中，有一个名为  &lt;code&gt;RNA&lt;/code&gt;  的 Assay。&lt;br /&gt;
 &lt;code&gt;RNA&lt;/code&gt;  的详细结构如下：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;layers&lt;/code&gt; ：存储多个层的数据。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;counts.GSE150703&lt;/code&gt;  和   &lt;code&gt;counts.GSE173079&lt;/code&gt;  是未归一化的原始计数矩阵，存储为稀疏矩阵格式（ &lt;code&gt;dgCMatrix&lt;/code&gt; ）。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;i&lt;/code&gt;  和  &lt;code&gt;p&lt;/code&gt; ：稀疏矩阵的内部索引，用于高效存储。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;Dim&lt;/code&gt; ：矩阵的行（基因）和列（细胞）维度。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;x&lt;/code&gt; ：非零元素的值。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;data.GSE150703&lt;/code&gt;  和  &lt;code&gt;data.GSE173079&lt;/code&gt;  是归一化后的基因表达矩阵。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;scale.data&lt;/code&gt; ：标准化后的矩阵，常用于降维和聚类分析。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;code&gt;cells&lt;/code&gt;  和  &lt;code&gt;features&lt;/code&gt; ：记录细胞和基因的相关信息。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt; &lt;code&gt;meta.data&lt;/code&gt; &lt;/strong&gt;：Assay 层级的元数据，包含变量基因的均值、方差等信息。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt; &lt;code&gt;key&lt;/code&gt; &lt;/strong&gt;：标记该 Assay 的前缀键，用于识别它的数据。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;metadata&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#metadata&#34;&gt;#&lt;/a&gt; meta.data&lt;/h3&gt;
&lt;p&gt;这是一个数据框，存储与每个细胞相关的元信息。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;示例中的字段：
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;orig.ident&lt;/code&gt; ：样本来源。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;nCount_RNA&lt;/code&gt; ：每个细胞的总 RNA 计数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;nFeature_RNA&lt;/code&gt; ：每个细胞检测到的基因数。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;percent_mito&lt;/code&gt; ：线粒体基因的比例，通常用于质量控制。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;percent_ribo&lt;/code&gt; ：核糖体基因占比，通常用于质量控制。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;percent_hb&lt;/code&gt; ：血红蛋白基因占比，通常用于质量控制。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;activeassay&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#activeassay&#34;&gt;#&lt;/a&gt; active.assay&lt;/h3&gt;
&lt;p&gt;表示当前活跃的 Assay，本例中是  &lt;code&gt;RNA&lt;/code&gt; 。它控制 Seurat 函数操作的数据来源。&lt;/p&gt;
&lt;h3 id=&#34;activeident&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#activeident&#34;&gt;#&lt;/a&gt; active.ident&lt;/h3&gt;
&lt;p&gt;每个细胞当前的分类标签，是一个因子型向量。在本例中，包含 8 个分组（如  &lt;code&gt;NORM&lt;/code&gt; 、 &lt;code&gt;OIR&lt;/code&gt; ），这些分组可以用于下游分析和绘图。&lt;/p&gt;
&lt;h3 id=&#34;graphs&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#graphs&#34;&gt;#&lt;/a&gt; graphs&lt;/h3&gt;
&lt;p&gt;存储细胞之间的图结构，支持聚类和邻近分析。本例中， &lt;code&gt;graphs&lt;/code&gt;  列表为空，表明暂未进行此类分析。&lt;/p&gt;
&lt;h3 id=&#34;neighbors&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#neighbors&#34;&gt;#&lt;/a&gt; neighbors&lt;/h3&gt;
&lt;p&gt;存储细胞间邻居信息，通常由最近邻算法计算得出，用于降维和聚类。本例中， &lt;code&gt;neighbors&lt;/code&gt;  列表为空。&lt;/p&gt;
&lt;h3 id=&#34;reductions&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#reductions&#34;&gt;#&lt;/a&gt; reductions&lt;/h3&gt;
&lt;p&gt;存储降维结果。本例中有一个 PCA（主成分分析）结果：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;cell.embeddings&lt;/code&gt; ：细胞在 PCA 空间中的坐标。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;feature.loadings&lt;/code&gt; ：基因对主成分的贡献。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;stdev&lt;/code&gt; ：每个主成分的标准差。 这些数据用于可视化（如 &lt;code&gt;DimPlot&lt;/code&gt; ）和聚类。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;images&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#images&#34;&gt;#&lt;/a&gt; images&lt;/h3&gt;
&lt;p&gt;存储空间转录组学数据的图像信息。本例中为空，表明未涉及空间转录组学分析。&lt;/p&gt;
&lt;h3 id=&#34;projectname&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#projectname&#34;&gt;#&lt;/a&gt; &lt;a href=&#34;http://project.name&#34;&gt;project.name&lt;/a&gt;&lt;/h3&gt;
&lt;p&gt;Seurat 对象的项目名称，本例为  &lt;code&gt;SeuratProject&lt;/code&gt; 。可用于标记和区分不同的数据集。&lt;/p&gt;
&lt;h3 id=&#34;misc&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#misc&#34;&gt;#&lt;/a&gt; misc&lt;/h3&gt;
&lt;p&gt;存储用户自定义的信息。本例中为空，可用于存储额外的分析结果或注释。&lt;/p&gt;
&lt;h3 id=&#34;version&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#version&#34;&gt;#&lt;/a&gt; version&lt;/h3&gt;
&lt;p&gt;记录 Seurat 包的版本号，本例为  &lt;code&gt;5.0.2&lt;/code&gt; 。这有助于保证分析结果的可重复性和兼容性。&lt;/p&gt;
&lt;h3 id=&#34;commands&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#commands&#34;&gt;#&lt;/a&gt; commands&lt;/h3&gt;
&lt;p&gt;记录分析过程中执行的主要命令及其参数。例如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;NormalizeData.RNA&lt;/code&gt; ：记录归一化步骤，使用了  &lt;code&gt;LogNormalize&lt;/code&gt;  方法。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;FindVariableFeatures.RNA&lt;/code&gt; ：记录高变基因筛选过程，选择了 2000 个基因。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;ScaleData.RNA&lt;/code&gt;  和  &lt;code&gt;RunPCA.RNA&lt;/code&gt; ：记录了标准化和 PCA 的参数。 这些信息便于追踪分析流程和复现结果。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;tools&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#tools&#34;&gt;#&lt;/a&gt; tools&lt;/h3&gt;
&lt;p&gt;存储插件或扩展分析的结果。本例中为空。&lt;/p&gt;
&lt;h3 id=&#34;基于本例的分析提示&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基于本例的分析提示&#34;&gt;#&lt;/a&gt; 基于本例的分析提示&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;code&gt;meta.data&lt;/code&gt;  是质量控制的重要部分，可通过筛选  &lt;code&gt;nFeature_RNA&lt;/code&gt;  和  &lt;code&gt;percent_mito&lt;/code&gt;  等字段过滤低质量细胞。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;reductions&lt;/code&gt;  的 PCA 结果是降维和聚类的基础，可以使用  &lt;code&gt;DimPlot&lt;/code&gt;  进行可视化。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;commands&lt;/code&gt;  记录了关键分析步骤，便于复现和审查。&lt;/li&gt;
&lt;/ol&gt;

 &lt;h1 id=&#34;两种富集分析的理解&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#两种富集分析的理解&#34;&gt;#&lt;/a&gt; 两种富集分析的理解&lt;/h1&gt;
&lt;p&gt;KEGG/GO 富集分析和 GSEA（基因集富集分析，Gene Set Enrichment Analysis）是两种不同但相关的分析方法，它们都有助于从基因表达数据中挖掘生物学意义，但它们的原理和使用场景有所不同。&lt;/p&gt;
&lt;h2 id=&#34;kegggo-富集分析&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#kegggo-富集分析&#34;&gt;#&lt;/a&gt; KEGG/GO 富集分析&lt;/h2&gt;
&lt;p&gt;KEGG/GO 富集分析是一种重要的基因功能注释和生物通路分析方法，通过统计学手段从基因列表中挖掘显著富集的功能注释（Gene Ontology, GO）或代谢通路（Kyoto Encyclopedia of Genes and Genomes, KEGG），以揭示基因表达变化的潜在生物学意义。&lt;/p&gt;
&lt;h3 id=&#34;一些概念&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#一些概念&#34;&gt;#&lt;/a&gt; 一些概念&lt;/h3&gt;
&lt;h4 id=&#34;基因功能注释go&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基因功能注释go&#34;&gt;#&lt;/a&gt; 基因功能注释（GO）&lt;/h4&gt;
&lt;p&gt;Gene Ontology（GO）是一套对基因及其产物的功能进行系统性描述的标准化术语，分为三个主要类别：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;生物学过程（Biological Process, BP）&lt;/strong&gt;：基因参与的生物学事件（如 “细胞增殖” 或 “信号转导”）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;分子功能（Molecular Function, MF）&lt;/strong&gt;：基因产物的具体功能（如 “ATP 结合” 或 “转录因子活性”）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;细胞组分（Cellular Component, CC）&lt;/strong&gt;：基因产物在细胞内的位置或组成部分（如 “线粒体” 或 “核糖体”）。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;代谢通路kegg&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#代谢通路kegg&#34;&gt;#&lt;/a&gt; 代谢通路（KEGG）&lt;/h4&gt;
&lt;p&gt;KEGG 数据库提供了基因在代谢和信号通路中的注释和网络信息，涵盖多种生物学过程，如代谢途径、环境适应以及人类疾病相关的信号通路。通过 KEGG 富集分析，可以揭示基因的生物学背景及其在复杂网络中的作用。&lt;/p&gt;
&lt;h4 id=&#34;背景基因集与目标基因集&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#背景基因集与目标基因集&#34;&gt;#&lt;/a&gt; 背景基因集与目标基因集&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;背景基因集&lt;/strong&gt;：在分析中定义的所有可能基因的集合（如全基因组或检测到的基因）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;目标基因集&lt;/strong&gt;：研究中筛选出的特定基因列表（如差异表达基因，DEGs）。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;核心方法过表达分析ora&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#核心方法过表达分析ora&#34;&gt;#&lt;/a&gt; 核心方法：过表达分析（ORA）&lt;/h3&gt;
&lt;h4 id=&#34;什么是过表达分析&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#什么是过表达分析&#34;&gt;#&lt;/a&gt; 什么是过表达分析？&lt;/h4&gt;
&lt;p&gt;过表达分析（Over-Representation Analysis, ORA）是一种统计方法，用于评估目标基因集中某些功能注释或通路的基因是否出现频率显著高于背景基因集。具体来说，它通过计算目标基因集中与某功能或通路相关的基因数量，与背景中的预期数量对比，确定是否显著富集。&lt;/p&gt;
&lt;h4 id=&#34;ora-的基本步骤&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ora-的基本步骤&#34;&gt;#&lt;/a&gt; ORA 的基本步骤&lt;/h4&gt;
&lt;ol&gt;
&lt;li&gt;首先定义一个目标基因集（如差异表达基因），从 GO 或 KEGG 数据库中检索基因的功能注释或通路信息。&lt;/li&gt;
&lt;li&gt;使用超几何检验或 Fisher 精确检验，计算这些功能注释中观察到的基因数量是否显著高于随机期望值。&lt;/li&gt;
&lt;li&gt;由于同时检测多个功能注释，需要进行校正（如 Benjamini-Hochberg 方法）以控制假阳性率。&lt;/li&gt;
&lt;/ol&gt;
&lt;h4 id=&#34;举例&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#举例&#34;&gt;#&lt;/a&gt; 举例&lt;/h4&gt;
&lt;p&gt;假设背景基因集中有 20,000 个基因，其中某条 KEGG 通路包含 50 个基因。在目标基因集（假设含 1,000 个基因）中，如果有 20 个基因属于该通路，则其富集程度可能高于随机预期（背景中比例为 50/20,000 = 0.0025，目标基因集比例为 20/1,000 = 0.02）。通过超几何检验和校正可以判断这种差异是否显著。&lt;/p&gt;
&lt;h3 id=&#34;富集分析的生物学意义&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#富集分析的生物学意义&#34;&gt;#&lt;/a&gt; 富集分析的生物学意义&lt;/h3&gt;
&lt;h4 id=&#34;揭示基因的功能背景&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#揭示基因的功能背景&#34;&gt;#&lt;/a&gt; 揭示基因的功能背景&lt;/h4&gt;
&lt;p&gt;KEGG/GO 富集分析可以从基因功能注释和通路角度为目标基因提供更深层次的生物学背景。例如，某些显著通路可能与研究对象的生物学现象（如疾病或胁迫响应）直接相关。&lt;/p&gt;
&lt;h4 id=&#34;提供研究线索&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#提供研究线索&#34;&gt;#&lt;/a&gt; 提供研究线索&lt;/h4&gt;
&lt;p&gt;显著富集的通路或功能术语可以帮助研究者快速定位关键的生物学过程或调控机制，为后续实验设计提供假设。&lt;/p&gt;
&lt;h4 id=&#34;定量评估通路的重要性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#定量评估通路的重要性&#34;&gt;#&lt;/a&gt; 定量评估通路的重要性&lt;/h4&gt;
&lt;p&gt;通过统计显著性评估（如 p 值或 FDR 校正值），富集分析为每个功能注释提供了可信度定量指标，便于研究者筛选和聚焦关键结果。&lt;/p&gt;
&lt;h3 id=&#34;kegggo-富集分析的优缺点&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#kegggo-富集分析的优缺点&#34;&gt;#&lt;/a&gt; KEGG/GO 富集分析的优缺点&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;快速功能注释。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;依赖基因筛选阈值&lt;/strong&gt;：只针对筛选出的目标基因，可能遗漏部分协同作用的基因。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;忽略基因之间的表达方向&lt;/strong&gt;：无法捕捉基因上调或下调的趋势。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;kegggo-富集分析的应用场景&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#kegggo-富集分析的应用场景&#34;&gt;#&lt;/a&gt; &lt;strong&gt;KEGG/GO 富集分析的应用场景&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;差异表达基因的功能注释&lt;/strong&gt;：通过分析差异基因，挖掘特定条件下的显著功能或通路。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;寻找疾病相关通路&lt;/strong&gt;：识别与特定疾病（如癌症）相关的通路，为治疗研究提供靶点。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;挖掘复杂生物学过程&lt;/strong&gt;：揭示多基因调控的生物学机制。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;gseagene-set-enrichment-analysis&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gseagene-set-enrichment-analysis&#34;&gt;#&lt;/a&gt; GSEA（Gene Set Enrichment Analysis）&lt;/h2&gt;
&lt;p&gt;GSEA（基因集富集分析）是一种基于整个基因表达谱的分析方法，通过对所有基因排序并评估预定义基因集（如功能注释或通路）在排名中的分布趋势，判断这些基因集是否表现出显著的协同上调或下调。GSEA 无需对基因表达设定显著性阈值，能够敏感地捕捉基因组层面的整体变化模式，特别适合分析微小但一致的调控趋势。&lt;/p&gt;
&lt;h3 id=&#34;一些概念-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#一些概念-2&#34;&gt;#&lt;/a&gt; 一些概念&lt;/h3&gt;
&lt;h4 id=&#34;基因集&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基因集&#34;&gt;#&lt;/a&gt; 基因集&lt;/h4&gt;
&lt;p&gt;GSEA 中的基因集是预定义的一组基因，通常根据其生物学功能、参与的信号通路或其他特定特性（如 GO 术语或 KEGG 通路）进行分类。例如，一个基因集可能包含所有参与 “细胞周期调控” 的基因。&lt;/p&gt;
&lt;h4 id=&#34;基因排序&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基因排序&#34;&gt;#&lt;/a&gt; 基因排序&lt;/h4&gt;
&lt;p&gt;GSEA 的核心在于将整个基因表达数据排序，通常依据某种统计指标（如差异表达分析中 Fold Change），形成从最显著上调到最显著下调的基因排序。&lt;/p&gt;
&lt;h4 id=&#34;富集分数enrichment-score-es&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#富集分数enrichment-score-es&#34;&gt;#&lt;/a&gt; 富集分数（Enrichment Score, ES）&lt;/h4&gt;
&lt;p&gt;富集分数用于衡量基因集中基因在整个排序中的分布趋势。如果一个基因集中的基因倾向于聚集在基因排序的顶部或底部，则该基因集的富集分数较高，说明其可能具有生物学显著性。&lt;/p&gt;
&lt;h3 id=&#34;核心方法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#核心方法&#34;&gt;#&lt;/a&gt; 核心方法&lt;/h3&gt;
&lt;h4 id=&#34;基因排序-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基因排序-2&#34;&gt;#&lt;/a&gt; 基因排序&lt;/h4&gt;
&lt;p&gt;根据基因表达差异的统计指标（如 Fold Change），对所有基因进行排序，形成从高到低的基因列表。&lt;/p&gt;
&lt;h4 id=&#34;计算富集分数es&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#计算富集分数es&#34;&gt;#&lt;/a&gt; 计算富集分数（ES）&lt;/h4&gt;
&lt;p&gt;针对每个基因集，沿排序基因列表逐步扫描：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果扫描到的基因属于当前基因集，则增加富集分数。&lt;/li&gt;
&lt;li&gt;如果扫描到的基因不属于基因集，则减少富集分数。&lt;/li&gt;
&lt;li&gt;最终的富集分数是整个扫描过程中的最大偏离值，表示基因集中基因在排序中的富集趋势。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;统计显著性评估&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#统计显著性评估&#34;&gt;#&lt;/a&gt; 统计显著性评估&lt;/h4&gt;
&lt;p&gt;通过随机置换方法生成背景分布，比较实际富集分数与置换的随机分布，计算 p 值以评估显著性。&lt;/p&gt;
&lt;h4 id=&#34;校正多重检验&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#校正多重检验&#34;&gt;#&lt;/a&gt; 校正多重检验&lt;/h4&gt;
&lt;p&gt;针对多个基因集进行的分析，GSEA 通过 False Discovery Rate（FDR）校正来控制假阳性。&lt;/p&gt;
&lt;h3 id=&#34;富集分析的生物学意义-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#富集分析的生物学意义-2&#34;&gt;#&lt;/a&gt; 富集分析的生物学意义&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;揭示基因表达的整体趋势&lt;/strong&gt;：GSEA 通过分析基因集的协同变化趋势，而非依赖单一基因的显著性，能够捕捉基因集整体的微弱调控模式。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;避免显著性阈值的限制&lt;/strong&gt;：传统方法需要设定显著性阈值筛选基因，而 GSEA 直接利用全基因表达数据，避免因阈值设定导致的信息丢失。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;探索基因集的潜在功能&lt;/strong&gt;：GSEA 不仅可以验证已知的功能基因集是否活跃，还能挖掘新的潜在基因集，从而揭示新的生物学机制。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;gsea-的优缺点&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gsea-的优缺点&#34;&gt;#&lt;/a&gt; GSEA 的优缺点&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;不依赖基因显著性筛选，利用全基因表达数据，信息更全面。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;能捕捉基因集的整体趋势，适合研究协同作用的基因集。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;对基因排序方式较敏感，不同排序方法可能影响结果。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;基因集中基因数量较少时，富集结果可能不稳定。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;gsea-的应用场景&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gsea-的应用场景&#34;&gt;#&lt;/a&gt; GSEA 的应用场景&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;差异表达基因的趋势分析&lt;/strong&gt;：在基因表达数据中，分析某些基因集（如通路或功能分类）的整体变化趋势。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;疾病或表型的功能富集&lt;/strong&gt;：研究与某种疾病或表型相关的基因集是否具有显著的调控趋势。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;药物靶标发现&lt;/strong&gt;：探索基因表达数据中潜在的药物靶标通路或功能。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;复杂调控网络解析&lt;/strong&gt;：通过基因集的富集分析揭示潜在的多基因调控机制。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;主要区别&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#主要区别&#34;&gt;#&lt;/a&gt; &lt;strong&gt;主要区别&lt;/strong&gt;&lt;/h3&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;&lt;strong&gt;特点&lt;/strong&gt;&lt;/th&gt;
&lt;th&gt;&lt;strong&gt;KEGG/GO 富集分析&lt;/strong&gt;&lt;/th&gt;
&lt;th&gt;&lt;strong&gt;GSEA&lt;/strong&gt;&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;输入数据&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;差异表达基因列表&lt;/td&gt;
&lt;td&gt;整个基因表达数据集&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;分析对象&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;GO 术语、KEGG 通路中显著富集的基因&lt;/td&gt;
&lt;td&gt;基因集在基因排名中的整体趋势&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;依赖基因筛选阈值&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;是（需要设定显著性阈值）&lt;/td&gt;
&lt;td&gt;否（基于全基因排序）&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;应用场景&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;显著基因功能注释与通路分析&lt;/td&gt;
&lt;td&gt;基因集整体的表达趋势分析&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;总结&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#总结&#34;&gt;#&lt;/a&gt; &lt;strong&gt;总结&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;两者有一定的互补性，适合不同的研究场景：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;KEGG/GO 富集分析&lt;/strong&gt;适合快速分析显著基因的功能或通路。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;GSEA&lt;/strong&gt; 适合挖掘基因表达谱的整体趋势，尤其是当单个基因的变化不显著但具有协同效应时。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;gsea-的结果图怎么看&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gsea-的结果图怎么看&#34;&gt;#&lt;/a&gt; GSEA 的结果图怎么看&lt;/h2&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; data-src=&#34;https://img.limina.top/blog/GSEA_PI3K-Akt.png&#34; alt=&#34;GSEA_PI3K-Akt&#34; /&gt;&lt;/p&gt;
&lt;p&gt;以上是一张典型的 GSEA（基因集富集分析）结果图，我们来解读一下：&lt;/p&gt;
&lt;h3 id=&#34;图的标题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#图的标题&#34;&gt;#&lt;/a&gt; 图的标题&lt;/h3&gt;
&lt;p&gt;图的标题是 “PI3K-Akt signaling pathway - Mus musculus (house mouse)”，表明这张图是针对小鼠的 PI3K-Akt 信号通路基因集的 GSEA 分析结果。&lt;/p&gt;
&lt;h3 id=&#34;上半部分running-enrichment-score&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#上半部分running-enrichment-score&#34;&gt;#&lt;/a&gt; 上半部分：Running Enrichment Score&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;绿色曲线代表 “运行富集分数”（Running Enrichment Score, ES）的变化情况。&lt;/li&gt;
&lt;li&gt;曲线通过沿着排序的基因列表逐步扫描基因集中的基因，计算 ES 得分。&lt;/li&gt;
&lt;li&gt;曲线的最高点（即最大富集分数，Maximum ES）表示基因集在基因排名中的最强富集位置。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;含义&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#含义&#34;&gt;#&lt;/a&gt; 含义&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;如果曲线的峰值（最高点）出现在排序靠前的位置，说明该基因集的基因在上调基因中富集。&lt;/li&gt;
&lt;li&gt;如果峰值出现在排序靠后的位置，说明该基因集的基因在下调基因中富集。&lt;/li&gt;
&lt;li&gt;本图中，绿色曲线的峰值靠近排序前半部分，说明 PI3K-Akt 通路基因在上调基因中显著富集。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;中间部分基因位置的条形标记&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#中间部分基因位置的条形标记&#34;&gt;#&lt;/a&gt; 中间部分：基因位置的条形标记&lt;/h3&gt;
&lt;h4 id=&#34;含义-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#含义-2&#34;&gt;#&lt;/a&gt; 含义&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;每一条垂直黑色线代表一个属于 PI3K-Akt 信号通路的基因在整个基因排序中的位置。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;基因越集中在排序的前半部分或后半部分，说明富集越显著。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;条形标记集中在排序的前段，进一步表明 PI3K-Akt 信号通路基因主要位于上调基因中。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;下半部分ranked-list-metric&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#下半部分ranked-list-metric&#34;&gt;#&lt;/a&gt; 下半部分：Ranked List Metric&lt;/h3&gt;
&lt;h4 id=&#34;含义-3&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#含义-3&#34;&gt;#&lt;/a&gt; 含义&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;这是基因表达排序的统计指标（如差异表达的 Fold Change）。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;左边值高（灰色柱状图较大）表示基因是上调的；右边值低表示基因是下调的。&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;本图中，灰色柱状图的左侧较高，说明上调基因在排序的前端，并且 PI3K-Akt 通路基因主要分布在这一部分。&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;富集分析的关键结果&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#富集分析的关键结果&#34;&gt;#&lt;/a&gt; 富集分析的关键结果&lt;/h3&gt;
&lt;h4 id=&#34;富集分数es和标准化富集分数nes&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#富集分数es和标准化富集分数nes&#34;&gt;#&lt;/a&gt; 富集分数（ES）和标准化富集分数（NES）&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;绿色曲线的峰值（最高点）代表最大富集分数（ES），用于衡量基因集在整个基因排序中的富集程度。&lt;/li&gt;
&lt;li&gt;该图中没有显示 NES 值，NES 是 GSEA 中的一个关键指标，它是对 ES 进行标准化后的结果，旨在消除基因集大小和排列随机性对富集分数的影响，从而更具比较性和可靠性。
&lt;ul&gt;
&lt;li&gt;NES &amp;gt; 0 表明基因集的基因倾向于出现在基因排名的顶部（通常与上调基因相关）。&lt;/li&gt;
&lt;li&gt;NES &amp;lt; 0 表明基因集的基因倾向于出现在基因排名的底部（通常与下调基因相关）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;p-值fdr-校正值&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#p-值fdr-校正值&#34;&gt;#&lt;/a&gt; p 值 / FDR 校正值&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;这两个值没有在图中展示，但在 GSEA 结果中通常提供。&lt;/li&gt;
&lt;li&gt;如果 p 值和 FDR 值显著（如 FDR &amp;lt; 0.25），说明该基因集的富集具有统计学意义。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;总结解读此图&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#总结解读此图&#34;&gt;#&lt;/a&gt; 总结解读此图&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;PI3K-Akt 信号通路的基因主要富集在基因排序的前端，说明这些基因在上调基因中显著富集。&lt;/li&gt;
&lt;li&gt;绿色曲线的峰值和条形标记的位置共同支持这一结果。&lt;/li&gt;
&lt;li&gt;如果 p 值和 FDR 值显著，则可以进一步认为 PI3K-Akt 通路在当前条件下可能受到激活或显著调控。&lt;/li&gt;
&lt;/ol&gt;

 &lt;blockquote&gt;
&lt;p&gt;这篇文章最初写于 2020 年，题为 &lt;code&gt;如何在 Ubuntu 下使用 QQ&lt;/code&gt; ，现在 QQ 官方已经发布了 Linux 版本，原文也由此成为时代的眼泪了...... 这些技术和技巧性的东西就是如此，有很强的时效性。5 年过去，也应当进行一些 ⌈老文翻新⌋ 了&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;基于-nonebot2-的-qq-机器人搭建&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基于-nonebot2-的-qq-机器人搭建&#34;&gt;#&lt;/a&gt; 基于 NoneBot2 的 QQ 机器人搭建&lt;/h2&gt;
&lt;h3 id=&#34;什么是-go-cqhttp&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#什么是-go-cqhttp&#34;&gt;#&lt;/a&gt; 什么是 go-cqhttp&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;go-cqhttp&lt;/strong&gt; 是一个基于 &lt;a href=&#34;https://github.com/botuniverse/onebot&#34;&gt;OneBot&lt;/a&gt; 协议实现的高性能 QQ 协议机器人框架，使用 Go 编程语言开发，轻量、易用且跨平台，支持运行在多种环境中（如 Windows、Linux、macOS 和 Docker）。go-cqhttp 主要用于构建 QQ 机器人，广泛应用于聊天管理、消息转发、自动回复等场景。&lt;/p&gt;
&lt;p&gt;过去的 QQ 机器人拓展功能大多基于 &lt;a href=&#34;https://github.com/Mrs4s/go-cqhttp&#34;&gt; &lt;code&gt;go-cqhttp&lt;/code&gt;  项目&lt;/a&gt;。但随着 QQ 使用了基于  &lt;code&gt;Electron&lt;/code&gt;  的新的  &lt;code&gt;QQNT&lt;/code&gt;  架构，此项目已经停止维护。&lt;/p&gt;
&lt;h3 id=&#34;关于无头-ntqq&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#关于无头-ntqq&#34;&gt;#&lt;/a&gt; 关于无头 NTQQ&lt;/h3&gt;
&lt;p&gt;NTQQ 客户端项目分为前后端两个部分，前端是使用 Web 技术开发的 UI 界面供用户交互，后端使用 nodejs addons 技术包装了一个库来处理客户端逻辑和与服务端通信 (wrapper.node)。这个库的作用和 go-cqhttp 非常相似，所以我们完全可以将前端删除只与这个库交互，并引出 API 来为我们的 Bot 服务。&lt;/p&gt;
&lt;p&gt;从服务端视角来说我们的 Bot 和正常客户端一样，因为都是通过 wrapper.node 与服务端通信。并且由于是官方根据内部文档开发的模块，我们可以说这是一个 完美 的 go-cqhttp。&lt;/p&gt;
&lt;h3 id=&#34;下载-python&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#下载-python&#34;&gt;#&lt;/a&gt; 下载 Python&lt;/h3&gt;
&lt;p&gt;版本需要在 3.9 以上，官网下载或者是使用 conda 都可以。&lt;/p&gt;
&lt;h3 id=&#34;安装-nb-cli-脚手架&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#安装-nb-cli-脚手架&#34;&gt;#&lt;/a&gt; 安装 nb-cli 脚手架&lt;/h3&gt;
&lt;h2 id=&#34;如何在-ubuntu-下使用-qq2020&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#如何在-ubuntu-下使用-qq2020&#34;&gt;#&lt;/a&gt; 如何在 Ubuntu 下使用 QQ（2020）&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;目前最简单的方法&lt;br /&gt;
这里写的很清楚：&lt;a href=&#34;https://github.com/zq1997/deepin-wine&#34;&gt;https://github.com/zq1997/deepin-wine&lt;/a&gt;&lt;br /&gt;
 不想跳转 Github 或者进不去的也可以直接看我的&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;用的是 deepin-wine 应用在 Ubuntu 上的移植仓库&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;顺便一提&lt;br /&gt;
 deepin 是个很好的国产 linux 系统，很漂亮（尤其 v20 大更后）&lt;br /&gt;
软件也比 Ubuntu 全（比如今天讲的 QQ，直接能在软件商店装了）&lt;br /&gt;
建议使用（我是自来水）&lt;br /&gt;
网址：&lt;a href=&#34;https://www.deepin.org/zh/&#34;&gt;https://www.deepin.org/zh/&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;我是因为之前 Web 课 xampp 的一些问题被迫转了 Ubuntu。&lt;br /&gt;
不过好在今年的 20.04 终于™变好看了，颜控福音&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;唔好像偏题了&lt;/p&gt;
&lt;h2 id=&#34;添加仓库&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#添加仓库&#34;&gt;#&lt;/a&gt; 添加仓库&lt;/h2&gt;
&lt;p&gt;首次使用时需要将移植仓库添加到系统中（没有 wget 的先 sudo 安装 wget）&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;figcaption data-lang=&#34;Bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;wget&lt;/span&gt; -O- https://deepin-wine.i-m.dev/setup.sh &lt;span class=&#34;token operator&#34;&gt;|&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;sudo&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;sh&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h2 id=&#34;应用安装&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#应用安装&#34;&gt;#&lt;/a&gt; 应用安装&lt;/h2&gt;
&lt;p&gt;也是用  &lt;code&gt;sudo apt-get install&lt;/code&gt;  安装的&lt;/p&gt;
&lt;p&gt;常用软件包的包名：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th style=&#34;text-align:center&#34;&gt;应用&lt;/th&gt;
&lt;th style=&#34;text-align:center&#34;&gt;包名&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:center&#34;&gt;QQ&lt;/td&gt;
&lt;td style=&#34;text-align:center&#34;&gt;com.qq.im.deepin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:center&#34;&gt;微信&lt;/td&gt;
&lt;td style=&#34;text-align:center&#34;&gt;com.qq.weixin.deepin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:center&#34;&gt;钉钉&lt;/td&gt;
&lt;td style=&#34;text-align:center&#34;&gt;com.dingtalk.deepin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:center&#34;&gt;QQ 音乐&lt;/td&gt;
&lt;td style=&#34;text-align:center&#34;&gt;com.qq.music.deepin&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:center&#34;&gt;…&lt;/td&gt;
&lt;td style=&#34;text-align:center&#34;&gt;…&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;比如我要安装 QQ：&lt;/p&gt;
&lt;figure class=&#34;highlight shell&#34;&gt;&lt;figcaption data-lang=&#34;Bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token function&#34;&gt;sudo&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;apt-get&lt;/span&gt; &lt;span class=&#34;token function&#34;&gt;install&lt;/span&gt; com.qq.im.deepin&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;p&gt;注意：2020 年 11 月 14 日更新以后需要注销 / 重启后才能看见启动台图标&lt;/p&gt;
&lt;h2 id=&#34;其他可能的问题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#其他可能的问题&#34;&gt;#&lt;/a&gt; 其他可能的问题&lt;/h2&gt;
&lt;p&gt;比如 QQ 头像无法加载、QQ 截图无法使用等&lt;/p&gt;
&lt;p&gt;我没遇到&lt;/p&gt;
&lt;p&gt;遇到再写&lt;/p&gt;
&lt;p&gt;Wine 不是 Windows&lt;/p&gt;
&lt;p&gt;我们只能尽可能的模拟&lt;/p&gt;
&lt;p&gt;“又不是不能用～”&lt;/p&gt;

 &lt;h1 id=&#34;单细胞转录组数据分析入门-2-各种格式的单细胞数据读取&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#单细胞转录组数据分析入门-2-各种格式的单细胞数据读取&#34;&gt;#&lt;/a&gt; 单细胞转录组数据分析入门 - 2 - 各种格式的单细胞数据读取&lt;/h1&gt;
&lt;blockquote&gt;
&lt;p&gt;单细胞转录组测序的格式可能有多种，包括单样本，多样本，10X 的标准输出文件，h5，h5ad，txt/csv/tsv&lt;/p&gt;
&lt;p&gt;网上的教程鱼龙混杂，这使我在初次接触时晕头转向&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h2 id=&#34;10x-标准输出&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#10x-标准输出&#34;&gt;#&lt;/a&gt; 10X 标准输出&lt;/h2&gt;
&lt;p&gt;这是目前比较主流的一种数据格式，对于一个样本，其包含：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;barcodes.tsv.gz&lt;/code&gt; ：记录 cell id&lt;/li&gt;
&lt;li&gt;&lt;code&gt;features.tsv.gz&lt;/code&gt; ：记录 gene id&lt;/li&gt;
&lt;li&gt;&lt;code&gt;matrix.mtx.gz&lt;/code&gt; ：计数 counts 矩阵&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;三个文件，且命名必须与上面&lt;strong&gt;完全相同&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;直接使用 Seurat 的  &lt;code&gt;Read10X()&lt;/code&gt;  函数读取即可&lt;/p&gt;
&lt;h3 id=&#34;如何读取多个样本&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#如何读取多个样本&#34;&gt;#&lt;/a&gt; 如何读取多个样本&lt;/h3&gt;
&lt;p&gt;通常，测序不会只测一个样本，那么如何读取多个样本呢？&lt;/p&gt;
&lt;p&gt;以 &lt;a href=&#34;https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE151177&#34;&gt;GSE151177&lt;/a&gt; 的读取为例：&lt;/p&gt;
&lt;p&gt;下载的数据为压缩包  &lt;code&gt;GSE151177_RAW.tar&lt;/code&gt; ，解压到  &lt;code&gt;GSE151177_RAW&lt;/code&gt;  文件夹中，此时所有样本的三个文件都在这个文件夹下&lt;/p&gt;
&lt;figure class=&#34;highlight bash&#34;&gt;&lt;figcaption data-lang=&#34;bash&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt; &lt;span class=&#34;token function&#34;&gt;ls&lt;/span&gt;                                                                                                                                                                                                                                  &lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    目录: D:&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Study&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;Project&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;GDG&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;scPsoriasis&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;data&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;GSE151177&lt;span class=&#34;token punctuation&#34;&gt;\&lt;/span&gt;GSE151177_RAW&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;Mode                 LastWriteTime         Length Name&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;----                 -------------         ------ ----&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;-a----         &lt;span class=&#34;token number&#34;&gt;5&lt;/span&gt;/24/2020  &lt;span class=&#34;token number&#34;&gt;10&lt;/span&gt;:59 AM          &lt;span class=&#34;token number&#34;&gt;13776&lt;/span&gt; GSM4567877_Control01_barcodes.tsv.gz&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&