&lt;td style=&#34;text-align:left&#34;&gt;MZB1, BRSK1, AC026202.3, JSRP1, LINC00582, PARM1, TAS1R3&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:left&#34;&gt;Progenitor&lt;/td&gt;
&lt;td style=&#34;text-align:left&#34;&gt;CD38, CASR, ALDH, CAR, KDR, MME, FLT3, CD90, CD123&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td style=&#34;text-align:left&#34;&gt;T cell&lt;/td&gt;
&lt;td style=&#34;text-align:left&#34;&gt;CD3D, CD3G, CD3E&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h3 id=&#34;小鼠细胞-marker&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#小鼠细胞-marker&#34;&gt;#&lt;/a&gt; 小鼠细胞 marker&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;B 细胞（B cell）&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Blnk, Cd79a, Cd79b&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;浆细胞（Plasma）&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Jchain&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;T 细胞（T cell）&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Cd3d, Cd3e, Cd3g&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;巨噬细胞（Macrophage）&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Itgax&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;树突状细胞 (DC)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Fcgr2b, Cd209a, Itgam&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;腔内 AV 细胞 (Luminal AV)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Mfge8, Trf, Csn3, Wfdc18, Elf5, Ltf&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;腔内 HS 细胞 (Luminal HS)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Prlr, Cited1, Pgr, Prom1, Esr1&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;肌上皮细胞 (Myoepithelial)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Krt17, Krt14, Krt5, Acta2, Myl9, Mylk, Myh11&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;成纤维细胞 (Fibroblast)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Col1a1, Col1a2, Col3a1, Fn1&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;血管细胞 (Vascular)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Pecam1, Cdh5, Eng, Pdgfra, Pdgfrb, Fap&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;周细胞 (Pericyte)&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;标记基因: Rgs5, Des, Notch3&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;文章及代码&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#文章及代码&#34;&gt;#&lt;/a&gt; 文章及代码&lt;/h3&gt;
&lt;h4 id=&#34;comprehensive-single-cell-aging-atlas-of-healthy-mammary-tissues-reveals-shared-epigenomic-and-transcriptomic-signatures-of-aging-and-cancer&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#comprehensive-single-cell-aging-atlas-of-healthy-mammary-tissues-reveals-shared-epigenomic-and-transcriptomic-signatures-of-aging-and-cancer&#34;&gt;#&lt;/a&gt; Comprehensive single-cell aging atlas of healthy mammary tissues reveals shared epigenomic and transcriptomic signatures of aging and cancer&lt;/h4&gt;
&lt;p&gt;&lt;a href=&#34;https://github.com/UcarLab/Mammary_gland_aging&#34;&gt;https://github.com/UcarLab/Mammary_gland_aging&lt;/a&gt;&lt;/p&gt;
&lt;h4 id=&#34;molecular-and-genetic-insights-into-human-ovarian-aging-from-single-nuclei-multi-omics-analyses&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#molecular-and-genetic-insights-into-human-ovarian-aging-from-single-nuclei-multi-omics-analyses&#34;&gt;#&lt;/a&gt; Molecular and genetic insights into human ovarian aging from single-nuclei multi-omics analyses&lt;/h4&gt;
&lt;p&gt;&lt;a href=&#34;https://github.com/ChenJin2020/Molecular-and-genetic-insights-into-human-ovarian-aging-from-single-nuclei-multi-omics-analyses&#34;&gt;https://github.com/ChenJin2020/Molecular-and-genetic-insights-into-human-ovarian-aging-from-single-nuclei-multi-omics-analyses&lt;/a&gt;&lt;/p&gt;

 &lt;h1 id=&#34;从零开始的-ai-学习-1-入门机器学习&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#从零开始的-ai-学习-1-入门机器学习&#34;&gt;#&lt;/a&gt; 从零开始的 AI 学习 - 1 - 入门机器学习&lt;/h1&gt;
&lt;h2 id=&#34;基本概念&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基本概念&#34;&gt;#&lt;/a&gt; 基本概念&lt;/h2&gt;
&lt;h3 id=&#34;特征feature&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#特征feature&#34;&gt;#&lt;/a&gt; 特征（Feature）&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;数据中的属性或变量，用于描述样本。
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;示例&lt;/strong&gt;：在房价预测中，房屋面积和房间数量是特征。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;标签label&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#标签label&#34;&gt;#&lt;/a&gt; 标签（Label）&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;监督学习中目标变量的真实值，用于训练模型。
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;示例&lt;/strong&gt;：房价预测中的真实房价。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模型&#34;&gt;#&lt;/a&gt; 模型&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;描述输入与输出之间映射关系的数学函数。
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;示例&lt;/strong&gt;：线性回归模型：&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;w&lt;/mi&gt;&lt;mo&gt;⋅&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;+&lt;/mo&gt;&lt;mi&gt;b&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;y = w \cdot x + b&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4445em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02691em;&#34;&gt;w&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;⋅&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;+&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;b&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模型训练与测试&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模型训练与测试&#34;&gt;#&lt;/a&gt; 模型训练与测试&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;训练集&lt;/strong&gt;：用于学习模型参数。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;测试集&lt;/strong&gt;：用于评估模型性能。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;模型评估&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#模型评估&#34;&gt;#&lt;/a&gt; 模型评估&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;通常，使用一些指标来衡量模型的性能，如：
&lt;ul&gt;
&lt;li&gt;准确率&lt;/li&gt;
&lt;li&gt;精确率&lt;/li&gt;
&lt;li&gt;召回率&lt;/li&gt;
&lt;li&gt;F1 分数&lt;/li&gt;
&lt;li&gt;等&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;监督学习supervised-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#监督学习supervised-learning&#34;&gt;#&lt;/a&gt; 监督学习（Supervised Learning）&lt;/h3&gt;
&lt;p&gt;监督学习是指模型在已标注的数据上进行训练，通过学习输入（特征）与输出（标签）之间的映射关系，从而预测未知数据的输出。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;输入与输出：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;输入：特征数据（如房价预测中的房屋面积、房间数量等）&lt;/li&gt;
&lt;li&gt;输出：标签（如对应房价）&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;目标：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;学习一个映射函数 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;f(x)&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 将输入 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;x&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4306em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 映射到输出 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;y&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.625em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;任务类型：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;分类任务&lt;/strong&gt;：输出为离散类别（如垃圾邮件检测、疾病诊断）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;回归任务&lt;/strong&gt;：输出为连续值（如房价预测、股票价格预测）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;示例算法：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;线性回归&lt;/li&gt;
&lt;li&gt;逻辑回归&lt;/li&gt;
&lt;li&gt;决策树&lt;/li&gt;
&lt;li&gt;支持向量机（SVM）&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;无监督学习unsupervised-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#无监督学习unsupervised-learning&#34;&gt;#&lt;/a&gt; 无监督学习（Unsupervised Learning）&lt;/h3&gt;
&lt;p&gt;无监督学习是指在未标注的数据上训练模型，发现数据的结构或模式，而无需明确的输出标签。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;输入：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;只有特征数据，没有对应标签。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;目标：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;找到数据的潜在结构或分布模式。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;任务类型：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;聚类&lt;/strong&gt;：将数据划分为多个组（如客户分群）。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;降维&lt;/strong&gt;：减少数据的维度，保留主要信息（如 PCA 降维）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;示例算法：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;K-means&lt;/li&gt;
&lt;li&gt;主成分分析（PCA）&lt;/li&gt;
&lt;li&gt;层次聚类&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;半监督学习semi-supervised-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#半监督学习semi-supervised-learning&#34;&gt;#&lt;/a&gt; 半监督学习（Semi-Supervised Learning）&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;数据中只有一部分是有标签的，其余是无标签的。&lt;/li&gt;
&lt;li&gt;通过结合监督和无监督方法，提高模型性能。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;强化学习reinforcement-learning&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#强化学习reinforcement-learning&#34;&gt;#&lt;/a&gt; 强化学习（Reinforcement Learning）&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;通过试错和环境交互，学习策略以获得最大化的奖励。&lt;/li&gt;
&lt;li&gt;应用于游戏 AI、自动驾驶等。&lt;/li&gt;
&lt;/ul&gt;

 &lt;h1 id=&#34;从零开始的-ai-学习-0-路径规划&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#从零开始的-ai-学习-0-路径规划&#34;&gt;#&lt;/a&gt; 从零开始的 AI 学习 - 0 - 路径规划&lt;/h1&gt;
&lt;ol&gt;
&lt;li&gt;
&lt;p&gt;入门机器学习：掌握机器学习的基本原理和方法&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;
&lt;p&gt;主题：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;监督学习与无监督学习的基本概念&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;常见算法：线性回归、逻辑回归、决策树、K-means&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;模型评估：交叉验证、混淆矩阵、ROC 曲线&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;实践：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;使用 Scikit-learn 进行模型训练&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;在 Kaggle 上完成基础的机器学习比赛，如 Titanic 数据集&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;深入学习深度学习：掌握神经网络和深度学习技术&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;
&lt;p&gt;主题：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;神经网络基础：前馈网络、激活函数、损失函数&lt;/li&gt;
&lt;li&gt;优化方法：梯度下降、反向传播。&lt;/li&gt;
&lt;li&gt;深度学习框架：TensorFlow 和 PyTorch&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;实践：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;实现简单的神经网络模型&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;用 Keras 或 PyTorch 构建图像分类、文本分类模型&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;参与 Kaggle 比赛：MNIST 手写数字识别&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;专项深入与项目实践：深入特定领域，完成实际项目&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;领域选择&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;计算机视觉&lt;/strong&gt;：图像处理、目标检测、生成对抗网络（GAN）&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;自然语言处理（NLP）&lt;/strong&gt;：词向量、Transformer、GPT、BERT&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;强化学习&lt;/strong&gt;：Q-learning、深度 Q 网络（DQN）&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;strong&gt;项目实践&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;图像识别项目（如自动驾驶）&lt;/li&gt;
&lt;li&gt;自然语言生成项目（如聊天机器人）&lt;/li&gt;
&lt;li&gt;强化学习项目（如游戏 AI）&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;我有 python 基础，但数学基础不太好，我使用 VSCode 进行开发&lt;/p&gt;

 &lt;h1 id=&#34;非负矩阵分解分析连续细胞状态&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#非负矩阵分解分析连续细胞状态&#34;&gt;#&lt;/a&gt; 非负矩阵分解分析连续细胞状态&lt;/h1&gt;
&lt;p&gt;在现代生物学研究中，理解细胞状态的多样性和连续性是揭示复杂生物过程的重要一步。&lt;/p&gt;
&lt;p&gt;无论是肿瘤微环境中的细胞演化，还是发育过程中的细胞分化，细胞状态的变化通常不是离散的，而是表现为一种渐变的连续谱。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;非负矩阵分解（Non-negative Matrix Factorization, NMF）&lt;/strong&gt; 能够有效提取和解释基因表达数据中的连续细胞状态。本文将探讨 NMF 在分析连续细胞状态中的应用原理及其生物学意义。&lt;/p&gt;
&lt;h2 id=&#34;非负矩阵分解nmf&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#非负矩阵分解nmf&#34;&gt;#&lt;/a&gt; 非负矩阵分解（NMF）&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;NMF&lt;/strong&gt; 是一种矩阵分解技术，用于将一个非负矩阵拆解为两个非负矩阵的乘积。形式上：&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;V&lt;/mi&gt;&lt;mo&gt;≈&lt;/mo&gt;&lt;mi&gt;W&lt;/mi&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;V \approx WH
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;V&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;≈&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;W&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;其中：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;V&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;V&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;V&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 是原始数据矩阵，通常是基因表达矩阵（行表示基因，列表示样本）。&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;W&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;W&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;W&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 是基矩阵，表示一组&lt;strong&gt;表达程序&lt;/strong&gt;，即基因的协同表达模式。&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;H&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 是系数矩阵，表示每个样本中各表达程序的权重。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;NMF 的核心特性在于非负性约束，即 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;W&lt;/mi&gt;&lt;mo&gt;≥&lt;/mo&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;W \geq 0&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8193em;vertical-align:-0.136em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;W&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;≥&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 和 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;mo&gt;≥&lt;/mo&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;H \geq 0&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8193em;vertical-align:-0.136em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;≥&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;。这一特性非常适合处理基因表达等非负数据，且结果具有自然的生物学可解释性。&lt;/p&gt;
&lt;h2 id=&#34;连续细胞状态&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#连续细胞状态&#34;&gt;#&lt;/a&gt; 连续细胞状态&lt;/h2&gt;
&lt;p&gt;在许多生物系统中，细胞状态并不是严格的离散类别，而是一种连续的渐变关系。例如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;在肿瘤微环境中，肿瘤核心细胞可能呈现强烈的增殖状态，而浸润边界的细胞则逐渐表现为侵袭特性。&lt;/li&gt;
&lt;li&gt;在发育过程中，干细胞可能逐步分化为不同类型的功能细胞，这些分化状态是连续变化的。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这种连续性在基因表达数据中表现为：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;多个基因表达模式的线性组合。&lt;/li&gt;
&lt;li&gt;不同样本中这些组合的权重连续变化。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;nmf-如何捕捉连续细胞状态&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#nmf-如何捕捉连续细胞状态&#34;&gt;#&lt;/a&gt; NMF 如何捕捉连续细胞状态？&lt;/h3&gt;
&lt;h4 id=&#34;数据表示与分解&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#数据表示与分解&#34;&gt;#&lt;/a&gt; 数据表示与分解&lt;/h4&gt;
&lt;p&gt;通过 NMF 分解，原始的基因表达矩阵 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;V&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;V&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;V&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 被分解为 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;W&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;W&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;W&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 和 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;H&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;W&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;W&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.13889em;&#34;&gt;W&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：表示一组表达程序（基因协同表达的模式）。&lt;/li&gt;
&lt;li&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;H&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;：表示每个样本中各表达程序的权重。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;这种分解让每个样本的基因表达被表示为若干表达程序的线性组合，其权重（即 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;H&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 的列向量）反映了样本中不同细胞状态的混合程度。&lt;/p&gt;
&lt;h4 id=&#34;稀疏性与非负性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#稀疏性与非负性&#34;&gt;#&lt;/a&gt; 稀疏性与非负性&lt;/h4&gt;
&lt;p&gt;NMF 的结果具有&lt;strong&gt;稀疏性&lt;/strong&gt;，即每个样本中只有少量表达程序对基因表达有显著贡献。这种特性保证了每个样本被清晰地分解为少数核心状态的组合。此外，非负性约束确保了分解结果符合生物学意义（如基因表达水平不能为负）。&lt;/p&gt;
&lt;h4 id=&#34;连续性的体现&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#连续性的体现&#34;&gt;#&lt;/a&gt; 连续性的体现&lt;/h4&gt;
&lt;p&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;H&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;H&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.08125em;&#34;&gt;H&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 矩阵的列向量表示样本中不同表达程序的权重：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;如果某个样本主要由一个表达程序主导，则可以被看作一种离散状态。&lt;/li&gt;
&lt;li&gt;如果某个样本的权重分布在多个表达程序上，并且这些权重在不同样本中连续变化，则说明这些样本处于连续细胞状态的渐变区。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;生物学意义从离散到连续的理解&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#生物学意义从离散到连续的理解&#34;&gt;#&lt;/a&gt; 生物学意义：从离散到连续的理解&lt;/h2&gt;
&lt;p&gt;传统的离散聚类方法（如 Leiden 聚类）能够将样本划分为明确的类别，但它无法捕捉细胞状态的渐变性。例如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;在肿瘤研究中，核心细胞和边界细胞可能被划分为不同的聚类，但两者之间的渐变过渡却被忽略。&lt;/li&gt;
&lt;li&gt;在免疫研究中，活化的免疫细胞和抑制状态的免疫细胞之间的状态转换可能无法用单一聚类方法解释。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;NMF 弥补了这一不足：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;离散性&lt;/strong&gt;：对于单一状态主导的样本，NMF 可以明确识别其核心特征。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;连续性&lt;/strong&gt;：对于多状态混合的样本，NMF 可以量化不同状态的贡献，并揭示状态之间的渐变关系。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;应用案例肿瘤微环境中的连续状态分析&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#应用案例肿瘤微环境中的连续状态分析&#34;&gt;#&lt;/a&gt; 应用案例：肿瘤微环境中的连续状态分析&lt;/h2&gt;
&lt;p&gt;在肿瘤研究中，NMF 被广泛用于揭示肿瘤组织中细胞状态的复杂性。以下是一个典型应用：&lt;/p&gt;
&lt;h3 id=&#34;数据背景&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#数据背景&#34;&gt;#&lt;/a&gt; &lt;strong&gt;数据背景&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;研究者对肿瘤样本的空间转录组数据进行了 NMF 分解。原始基因表达矩阵包含了肿瘤核心区、浸润边界和周围正常组织的基因表达。&lt;/p&gt;
&lt;h3 id=&#34;分解结果&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#分解结果&#34;&gt;#&lt;/a&gt; &lt;strong&gt;分解结果&lt;/strong&gt;&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;表达程序（W）&lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;程序 1：增殖相关基因高表达，可能对应于肿瘤核心细胞。&lt;/li&gt;
&lt;li&gt;程序 2：侵袭相关基因高表达，可能对应于浸润性肿瘤细胞。&lt;/li&gt;
&lt;li&gt;程序 3：免疫活化相关基因高表达，可能对应于免疫细胞的功能状态。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;权重矩阵（H）&lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;样本中权重的连续变化显示，从肿瘤核心到边界，增殖程序的权重逐渐减弱，而侵袭程序的权重逐渐增强。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;生物学洞察&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#生物学洞察&#34;&gt;#&lt;/a&gt; &lt;strong&gt;生物学洞察&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;NMF 结果揭示了肿瘤细胞从核心增殖状态到边界侵袭状态的渐变过程，并且量化了免疫细胞在不同区域的活化程度。这为理解肿瘤微环境的动态特性提供了新视角。&lt;/p&gt;
&lt;h2 id=&#34;nmf-与离散方法的比较&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#nmf-与离散方法的比较&#34;&gt;#&lt;/a&gt; NMF 与离散方法的比较&lt;/h2&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;特性&lt;/th&gt;
&lt;th&gt;NMF&lt;/th&gt;
&lt;th&gt;离散聚类（如 Leiden）&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;数据表示&lt;/td&gt;
&lt;td&gt;线性组合的连续表示&lt;/td&gt;
&lt;td&gt;离散类别分配&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;细胞状态的捕捉&lt;/td&gt;
&lt;td&gt;连续状态的渐变&lt;/td&gt;
&lt;td&gt;离散状态&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;生物学意义&lt;/td&gt;
&lt;td&gt;解释细胞状态之间的过渡关系&lt;/td&gt;
&lt;td&gt;强调类别的差异性&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;应用场景&lt;/td&gt;
&lt;td&gt;分析复杂、异质性高的数据&lt;/td&gt;
&lt;td&gt;分类明确、异质性低的数据&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;

 &lt;h1 id=&#34;跨多个通路的-degs-可视化&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#跨多个通路的-degs-可视化&#34;&gt;#&lt;/a&gt; 跨多个通路的 DEGs 可视化&lt;/h1&gt;
&lt;p&gt;报错的原因是  &lt;code&gt;scale_fill_manual()&lt;/code&gt;  提供的颜色向量  &lt;code&gt;custom_colors&lt;/code&gt;  中的颜色数量不足以覆盖  &lt;code&gt;geom_scatterpie&lt;/code&gt;  内使用的  &lt;code&gt;cols&lt;/code&gt;  所对应的路径数量，导致了 “需要 11 个颜色，但只提供了 9 个” 的错误。&lt;/p&gt;
&lt;h3 id=&#34;原因分析&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#原因分析&#34;&gt;#&lt;/a&gt; &lt;strong&gt;原因分析&lt;/strong&gt;&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt; &lt;code&gt;scale_fill_manual()&lt;/code&gt; &lt;/strong&gt; 会同时影响所有使用  &lt;code&gt;fill&lt;/code&gt;  映射的几何对象，包括：
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;geom_scatterpie&lt;/code&gt; （用于 pathways 和器官分布）&lt;/li&gt;
&lt;li&gt;&lt;code&gt;geom_label_repel&lt;/code&gt; （用于标签背景颜色）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;冲突&lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;custom_colors&lt;/code&gt;  颜色向量只为  &lt;code&gt;geom_scatterpie&lt;/code&gt;  的 pathways 提供了 9 种颜色。&lt;/li&gt;
&lt;li&gt;同时  &lt;code&gt;geom_label_repel&lt;/code&gt;  使用  &lt;code&gt;fill&lt;/code&gt;  映射来设置标签的背景色（红色和白色），这会造成颜色不足的错误。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;hr /&gt;
&lt;h2 id=&#34;解决方案&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#解决方案&#34;&gt;#&lt;/a&gt; &lt;strong&gt;解决方案&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;将  &lt;code&gt;scale_fill_manual()&lt;/code&gt;  和  &lt;code&gt;geom_label_repel()&lt;/code&gt;  的  &lt;code&gt;fill&lt;/code&gt;  设置分开处理，确保路径（ &lt;code&gt;geom_scatterpie&lt;/code&gt; ）和标签背景色互不干扰。&lt;/p&gt;
&lt;h3 id=&#34;方法一为-geom_scatterpie-使用-scale_fill_manual&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#方法一为-geom_scatterpie-使用-scale_fill_manual&#34;&gt;#&lt;/a&gt; &lt;strong&gt;方法一：为  &lt;code&gt;geom_scatterpie&lt;/code&gt;  使用  &lt;code&gt;scale_fill_manual()&lt;/code&gt; &lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;同时在  &lt;code&gt;geom_label_repel()&lt;/code&gt;  中使用固定的  &lt;code&gt;fill&lt;/code&gt;  值，不依赖  &lt;code&gt;scale_fill_manual()&lt;/code&gt; 。&lt;/p&gt;
&lt;figure class=&#34;highlight r&#34;&gt;&lt;figcaption data-lang=&#34;r&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;test &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; g3 &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  ggforce&lt;span class=&#34;token operator&#34;&gt;::&lt;/span&gt;geom_mark_rect&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;aes&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;x &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; x&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; y &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; y&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; group &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; walktrap&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; color &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;grey&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  geom_scatterpie&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;aes&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;x &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; x&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; y &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; y&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; r &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; size &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0.1&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  color &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;transparent&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  legend_name &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Pathway&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; graphdata&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  cols &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; pathways&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  geom_scatterpie&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;aes&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;x &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; x&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; y &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; y&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; r &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; size&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  color &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;transparent&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; graphdata&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; legend_name &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;enrich&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;                  cols &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; organ_columns&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  scale_fill_manual&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;values &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; custom_colors&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; name &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;Pathways&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;# 仅控制 pathways 的填充颜色&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  geom_node_point&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;shape &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;19&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; size &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; aes&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;filter &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; no_organ &lt;span class=&#34;token operator&#34;&gt;&amp;amp;&lt;/span&gt; type &lt;span class=&#34;token operator&#34;&gt;!=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;map&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token comment&#34;&gt;# 修复 geom_label_repel 的 fill，使其不受 scale_fill_manual 影响&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;16&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  ggrepel&lt;span class=&#34;token operator&#34;&gt;::&lt;/span&gt;geom_label_repel&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;17&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    data &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; graphdata&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;18&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    aes&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;x &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; x&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; y &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; y&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; label &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; id&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;19&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    fill &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; ifelse&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;graphdata&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt;is_top_node&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;red&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;white&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;# 直接设置标签的背景颜色&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;20&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    color &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; ifelse&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;graphdata&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt;is_top_node&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;white&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;black&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token comment&#34;&gt;# 文字颜色&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;21&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    fontface &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; ifelse&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;graphdata&lt;span class=&#34;token operator&#34;&gt;$&lt;/span&gt;is_top_node&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;bold&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;plain&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;22&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    size &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;3&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;23&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    box.padding &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0.5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;24&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    label.size &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0.5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;25&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    segment.color &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;grey50&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;26&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    segment.size &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0.5&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;27&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    max.overlaps &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;Inf&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;28&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;    min.segment.length &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token number&#34;&gt;0&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;29&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  &lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;30&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  scale_colour_identity&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;31&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  theme_void&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token operator&#34;&gt;+&lt;/span&gt; coord_fixed&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h3 id=&#34;关键修正点&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#关键修正点&#34;&gt;#&lt;/a&gt; &lt;strong&gt;关键修正点&lt;/strong&gt;&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt; &lt;code&gt;geom_label_repel()&lt;/code&gt; &lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt; &lt;code&gt;fill&lt;/code&gt;  参数&lt;/strong&gt;：直接在  &lt;code&gt;geom_label_repel&lt;/code&gt;  内部指定背景颜色，而不是通过  &lt;code&gt;aes()&lt;/code&gt;  使用全局的  &lt;code&gt;scale_fill_manual()&lt;/code&gt; 。&lt;/li&gt;
&lt;li&gt;这样标签背景色（红色和白色）不会受到  &lt;code&gt;scale_fill_manual()&lt;/code&gt;  的影响。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt; &lt;code&gt;scale_fill_manual()&lt;/code&gt; &lt;/strong&gt;：
&lt;ul&gt;
&lt;li&gt;仅用于  &lt;code&gt;geom_scatterpie&lt;/code&gt;  控制饼图的填充颜色，不会干扰其他对象。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;

 &lt;h1 id=&#34;使用-ensembl-api-查询-snp-在不同人群中的分布&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#使用-ensembl-api-查询-snp-在不同人群中的分布&#34;&gt;#&lt;/a&gt; 使用 Ensembl API 查询 SNP 在不同人群中的分布&lt;/h1&gt;
&lt;p&gt;Ensembl REST API 的端点和测试用例可以在&lt;a href=&#34;https://rest.ensembl.org/&#34;&gt;这里&lt;/a&gt;找到。本文以 R 语言为例，介绍如何使用 Ensembl API 查询特定单核苷酸多态性（SNP）的分布情况，包括单个和批量查询的实现过程。&lt;/p&gt;
&lt;h2 id=&#34;为什么要查询-snp-的分布&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#为什么要查询-snp-的分布&#34;&gt;#&lt;/a&gt; 为什么要查询 SNP 的分布？&lt;/h2&gt;
&lt;p&gt;SNP（单核苷酸多态性）是基因组中常见的变异形式，对研究基因与表型的关系、疾病关联分析和个性化医疗至关重要。SNP 在不同人群中的分布往往因种群历史、地理分布和自然选择而异，因此理解这些分布特征是遗传学研究的重要任务。&lt;/p&gt;
&lt;h2 id=&#34;准备工作&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#准备工作&#34;&gt;#&lt;/a&gt; 准备工作&lt;/h2&gt;
&lt;p&gt;需要加载几个 R 包来完成请求和数据处理：&lt;/p&gt;
&lt;figure class=&#34;highlight r&#34;&gt;&lt;figcaption data-lang=&#34;r&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;library&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;httr&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;       &lt;span class=&#34;token comment&#34;&gt;# 用于发送 HTTP 请求&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;library&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;jsonlite&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;   &lt;span class=&#34;token comment&#34;&gt;# 用于解析和构造 JSON 数据&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;library&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;dplyr&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;      &lt;span class=&#34;token comment&#34;&gt;# 用于数据操作&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h2 id=&#34;单个-snp-的查询&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#单个-snp-的查询&#34;&gt;#&lt;/a&gt; 单个 SNP 的查询&lt;/h2&gt;
&lt;h3 id=&#34;api-调用和数据处理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#api-调用和数据处理&#34;&gt;#&lt;/a&gt; API 调用和数据处理&lt;/h3&gt;
&lt;p&gt;以下代码实现了查询单个 SNP ( &lt;code&gt;rs3762444&lt;/code&gt; ) 的频率分布：&lt;/p&gt;
&lt;figure class=&#34;highlight r&#34;&gt;&lt;figcaption data-lang=&#34;r&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;server &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;https://grch37.rest.ensembl.org&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;ext &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;/variation/human/rs3762444?pops=1&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;r &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; GET&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;paste&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;server&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; ext&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sep &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; content_type&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;stop_for_status&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;r&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;response &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; content&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;r&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; as &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;parsed&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; type &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;pg &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; response&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;populations&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token percent-operator operator&#34;&gt;%&gt;%&lt;/span&gt; bind_rows&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;lapply&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;.&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; as.data.frame&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;print&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;pg&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h3 id=&#34;代码解析&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#代码解析&#34;&gt;#&lt;/a&gt; 代码解析&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;API URL 构建：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;server&lt;/code&gt;  是 Ensembl API 的基础 URL。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;ext&lt;/code&gt;  是指定资源的扩展路径，包括要查询的 SNP ID（ &lt;code&gt;rs3762444&lt;/code&gt; ）和额外参数（ &lt;code&gt;pops=1&lt;/code&gt;  表示返回人群频率信息）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;发送 GET 请求：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;使用  &lt;code&gt;GET&lt;/code&gt;  方法向服务器发送请求，并确保请求成功（ &lt;code&gt;stop_for_status&lt;/code&gt; ）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;数据解析：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;response&lt;/code&gt;  包含服务器返回的 JSON 数据。&lt;/li&gt;
&lt;li&gt;提取  &lt;code&gt;populations&lt;/code&gt;  字段（包含频率数据）并将其转换为数据框格式。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;输出结果&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#输出结果&#34;&gt;#&lt;/a&gt; 输出结果&lt;/h3&gt;
&lt;p&gt;查询结果  &lt;code&gt;pg&lt;/code&gt;  是一个数据框，展示了  &lt;code&gt;rs3762444&lt;/code&gt;  在不同人群中的频率分布。例如：&lt;/p&gt;
&lt;table&gt;
&lt;thead&gt;
&lt;tr&gt;
&lt;th&gt;Population Name&lt;/th&gt;
&lt;th&gt;Allele&lt;/th&gt;
&lt;th&gt;Frequency&lt;/th&gt;
&lt;/tr&gt;
&lt;/thead&gt;
&lt;tbody&gt;
&lt;tr&gt;
&lt;td&gt;1000GENOMES:AFR&lt;/td&gt;
&lt;td&gt;T&lt;/td&gt;
&lt;td&gt;0.123&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;1000GENOMES:EUR&lt;/td&gt;
&lt;td&gt;C&lt;/td&gt;
&lt;td&gt;0.789&lt;/td&gt;
&lt;/tr&gt;
&lt;/tbody&gt;
&lt;/table&gt;
&lt;h2 id=&#34;批量查询多个-snp&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#批量查询多个-snp&#34;&gt;#&lt;/a&gt; 批量查询多个 SNP&lt;/h2&gt;
&lt;p&gt;当需要查询多个 SNP 时，可以使用 POST 请求。以下代码实现了批量查询：&lt;/p&gt;
&lt;figure class=&#34;highlight r&#34;&gt;&lt;figcaption data-lang=&#34;r&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;server &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;https://grch37.rest.ensembl.org&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;ext &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;/variation/homo_sapiens?pops=1&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;body &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; list&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  ids &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; list&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;rs3762444&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;rs284262&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;rs655598&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;json_body &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; toJSON&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;body&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; auto_unbox &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token boolean&#34;&gt;TRUE&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; pretty &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token boolean&#34;&gt;TRUE&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;r &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; POST&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;paste&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;server&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; ext&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sep &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;          content_type&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;          accept&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;          body &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; json_body&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;stop_for_status&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;r&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;response &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; content&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;r&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; as &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;parsed&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; type &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;16&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;17&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;pg &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; lapply&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;response&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;token keyword&#34;&gt;function&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;data&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;token punctuation&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;18&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;  bind_rows&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;lapply&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;data&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;populations&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; as.data.frame&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;19&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token punctuation&#34;&gt;&amp;#125;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;20&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;21&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;print&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;pg&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;h3 id=&#34;代码解析-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#代码解析-2&#34;&gt;#&lt;/a&gt; 代码解析&lt;/h3&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;构建请求体：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;使用一个列表  &lt;code&gt;body&lt;/code&gt;  指定要查询的多个 SNP ID。&lt;/li&gt;
&lt;li&gt;将列表转换为 JSON 格式（ &lt;code&gt;toJSON&lt;/code&gt; ）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;发送 POST 请求：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;使用  &lt;code&gt;POST&lt;/code&gt;  方法发送请求，并指定  &lt;code&gt;body&lt;/code&gt; 。&lt;/li&gt;
&lt;li&gt;设置 HTTP headers，包括  &lt;code&gt;content_type&lt;/code&gt;  和  &lt;code&gt;accept&lt;/code&gt; 。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;解析结果：&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;response&lt;/code&gt;  是一个列表，包含每个 SNP 的查询结果。&lt;/li&gt;
&lt;li&gt;遍历结果，提取  &lt;code&gt;populations&lt;/code&gt;  字段并转换为数据框。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;h3 id=&#34;输出结果-2&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#输出结果-2&#34;&gt;#&lt;/a&gt; 输出结果&lt;/h3&gt;
&lt;p&gt;批量查询结果  &lt;code&gt;pg&lt;/code&gt;  是一个列表，其中每个元素对应一个 SNP 的频率数据。例如：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;pg[[1]]&lt;/code&gt;  是  &lt;code&gt;rs3762444&lt;/code&gt;  的频率分布。&lt;/li&gt;
&lt;li&gt;&lt;code&gt;pg[[2]]&lt;/code&gt;  是  &lt;code&gt;rs284262&lt;/code&gt;  的频率分布。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;每个数据框的结构类似于单个查询的结果。&lt;/p&gt;
&lt;h2 id=&#34;完整代码&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#完整代码&#34;&gt;#&lt;/a&gt; 完整代码&lt;/h2&gt;
&lt;figure class=&#34;highlight r&#34;&gt;&lt;figcaption data-lang=&#34;r&#34;&gt;&lt;/figcaption&gt;&lt;table&gt;&lt;tr&gt;&lt;td data-num=&#34;1&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;library&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;httr&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;2&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;library&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;jsonlite&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;3&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;library&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;dplyr&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;4&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;5&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;################################### 单个 ###################################&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;6&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;rm&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;list &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; ls&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;7&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;setwd&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;D:/Study/Project/GDG/labtd/workfile/other/黄煜/20241206&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;server &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;https://grch37.rest.ensembl.org&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;ext &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;/variation/human/rs3762444?pops=1&#34;&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;r &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; GET&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;paste&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;server&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; ext&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; sep &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; content_type&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;stop_for_status&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;r&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;response &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; content&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;r&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; as &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;parsed&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; type &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;application/json&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;16&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;pg &lt;span class=&#34;token operator&#34;&gt;&amp;lt;-&lt;/span&gt; response&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;populations&#34;&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;token percent-operator operator&#34;&gt;%&gt;%&lt;/span&gt; bind_rows&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;lapply&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;.&lt;span class=&#34;token punctuation&#34;&gt;,&lt;/span&gt; as.data.frame&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;17&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;18&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;19&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;################################### 批量 #